    const out = addItem([{ i: 'a', x: 0, y: 0, w: 6, h: 2 }], { i: 'n', x: 0, y: 0, w: 4, h: 2 }, COLS);
    expect(pos(out, 'n')).toMatchObject({ x: 6, y: 0 });
  });
