import React from 'react';

import { type Layout, type LayoutItem, bottom, moveItem, resizeItem } from './layout';
import { useElementSize } from '../useElementSize';
import './grid.css';

export interface ItemControls {
  /** Spread on the element that starts a drag (pointer) and moves/resizes by keyboard. */
  handleProps: React.HTMLAttributes<HTMLElement>;
  /** Whether the grid is in a mode where items can be rearranged. */
  editable: boolean;
  active: boolean;
}

interface Props {
  layout: Layout;
  onLayoutChange: (layout: Layout) => void;
  renderItem: (item: LayoutItem, controls: ItemControls) => React.ReactNode;
  getItemLabel: (id: string) => string;
  cols?: number;
  rowHeight?: number;
  gap?: number;
  /** Below this container width the grid collapses into one column (read-only). */
  stackBelow?: number;
}

interface Rect {
  left: number;
  top: number;
  width: number;
  height: number;
}

interface Interaction {
  kind: 'move' | 'resize';
  id: string;
  pointerId: number;
  startLayout: Layout;
  startClient: { x: number; y: number };
  startScrollY: number;
  startRect: Rect;
  lastClient: { x: number; y: number };
}

const EDGE = 48;

export function GridLayout({
  layout,
  onLayoutChange,
  renderItem,
  getItemLabel,
  cols = 12,
  rowHeight = 56,
  gap = 12,
  stackBelow = 720,
}: Props) {
  const [containerRef, size] = useElementSize<HTMLDivElement>();
  const width = size.width;
  const stacked = width > 0 && width < stackBelow;
  const colWidth = Math.max(0, (width - gap * (cols - 1)) / cols);

  const [preview, setPreview] = React.useState<Layout | null>(null);
  const [ghost, setGhost] = React.useState<{ id: string; rect: Rect; kind: Interaction['kind'] } | null>(null);
  const [announcement, setAnnouncement] = React.useState('');
  const interaction = React.useRef<Interaction | null>(null);
  const scrollTimer = React.useRef<number | null>(null);

  const toRect = React.useCallback(
    (it: Pick<LayoutItem, 'x' | 'y' | 'w' | 'h'>): Rect => ({
      left: it.x * (colWidth + gap),
      top: it.y * (rowHeight + gap),
      width: it.w * colWidth + (it.w - 1) * gap,
      height: it.h * rowHeight + (it.h - 1) * gap,
    }),
    [colWidth, gap, rowHeight],
  );

  const describe = (it: LayoutItem) =>
    `${getItemLabel(it.i)}: колонка ${it.x + 1}, строка ${it.y + 1}, ширина ${it.w}, высота ${it.h}`;

  // ---- pointer interaction -------------------------------------------------

  const update = React.useCallback(() => {
    const act = interaction.current;
    if (!act) return;
    const dx = act.lastClient.x - act.startClient.x;
    const dy = act.lastClient.y - act.startClient.y + (window.scrollY - act.startScrollY);
    const stepX = colWidth + gap;
    const stepY = rowHeight + gap;
    const item = act.startLayout.find((it) => it.i === act.id)!;

    if (act.kind === 'move') {
      const rect = {
        ...act.startRect,
        left: Math.max(0, Math.min(width - act.startRect.width, act.startRect.left + dx)),
        top: Math.max(0, act.startRect.top + dy),
      };
      setGhost({ id: act.id, rect, kind: 'move' });
      setPreview(moveItem(act.startLayout, act.id, Math.round(rect.left / stepX), Math.round(rect.top / stepY), cols));
    } else {
      const minW = (item.minW ?? 1) * colWidth + ((item.minW ?? 1) - 1) * gap;
      const minH = (item.minH ?? 1) * rowHeight + ((item.minH ?? 1) - 1) * gap;
      const rect = {
        ...act.startRect,
        width: Math.max(minW, Math.min(width - act.startRect.left, act.startRect.width + dx)),
        height: Math.max(minH, act.startRect.height + dy),
      };
      setGhost({ id: act.id, rect, kind: 'resize' });
      setPreview(
        resizeItem(act.startLayout, act.id, Math.round((rect.width + gap) / stepX), Math.round((rect.height + gap) / stepY), cols),
      );
    }
  }, [colWidth, cols, gap, rowHeight, width]);

  const stopAutoScroll = () => {
    if (scrollTimer.current !== null) cancelAnimationFrame(scrollTimer.current);
    scrollTimer.current = null;
  };

  const autoScroll = React.useCallback(() => {
    const act = interaction.current;
    if (!act) return stopAutoScroll();
    const y = act.lastClient.y;
    const speed = y > window.innerHeight - EDGE ? 12 : y < EDGE ? -12 : 0;
    if (speed !== 0) {
      const before = window.scrollY;
      window.scrollBy(0, speed);
      if (window.scrollY !== before) update();
    }
    scrollTimer.current = requestAnimationFrame(autoScroll);
  }, [update]);

  const finish = React.useCallback(
    (commit: boolean) => {
      const act = interaction.current;
      interaction.current = null;
      stopAutoScroll();
      document.body.classList.remove('grid-dragging', 'grid-resizing');
      setGhost(null);
      setPreview((current) => {
        if (commit && act && current) {
          onLayoutChange(current);
          const it = current.find((l) => l.i === act.id);
          if (it) setAnnouncement(describe(it));
        }
        return null;
      });
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [onLayoutChange],
  );

  React.useEffect(() => {
    const onMove = (e: PointerEvent) => {
      const act = interaction.current;
      if (!act || e.pointerId !== act.pointerId) return;
      act.lastClient = { x: e.clientX, y: e.clientY };
      update();
    };
    const onUp = (e: PointerEvent) => {
      if (interaction.current?.pointerId === e.pointerId) finish(e.type === 'pointerup');
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && interaction.current) finish(false);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
      window.removeEventListener('keydown', onKey);
    };
  }, [finish, update]);

  React.useEffect(() => stopAutoScroll, []);

  const begin = (kind: Interaction['kind'], item: LayoutItem) => (e: React.PointerEvent<HTMLElement>) => {
    if (stacked || e.button !== 0 || interaction.current) return;
    // Let buttons inside the handle (e.g. "remove") work normally.
    if (kind === 'move' && (e.target as HTMLElement).closest('button:not([data-grid-handle]), a, input')) return;
    e.preventDefault();
    interaction.current = {
      kind,
      id: item.i,
      pointerId: e.pointerId,
      startLayout: layout,
      startClient: { x: e.clientX, y: e.clientY },
      startScrollY: window.scrollY,
      startRect: toRect(item),
      lastClient: { x: e.clientX, y: e.clientY },
    };
    document.body.classList.add(kind === 'move' ? 'grid-dragging' : 'grid-resizing');
    setPreview(layout);
    setGhost({ id: item.i, rect: toRect(item), kind });
    scrollTimer.current = requestAnimationFrame(autoScroll);
  };

  // ---- keyboard interaction --------------------------------------------------

  const onHandleKeyDown = (item: LayoutItem) => (e: React.KeyboardEvent<HTMLElement>) => {
    if (stacked) return;
    const delta: Record<string, [number, number]> = {
      ArrowLeft: [-1, 0],
      ArrowRight: [1, 0],
      ArrowUp: [0, -1],
      ArrowDown: [0, 1],
    };
    const d = delta[e.key];
    if (!d) return;
    e.preventDefault();
    let next: Layout;
    if (e.shiftKey) {
      next = resizeItem(layout, item.i, item.w + d[0], item.h + d[1], cols);
    } else if (d[1] > 0) {
      // Moving down must jump past the neighbour below, otherwise gravity snaps it back.
      const below = layout
        .filter((o) => o.i !== item.i && o.x < item.x + item.w && o.x + o.w > item.x && o.y >= item.y + item.h)
        .sort((a, b) => a.y - b.y)[0];
      next = moveItem(layout, item.i, item.x, below ? below.y + below.h - item.h + 1 : item.y + 1, cols);
      if (below && next.find((it) => it.i === item.i)!.y <= item.y) {
        next = moveItem(layout, item.i, item.x, below.y + below.h, cols);
      }
    } else {
      next = moveItem(layout, item.i, item.x + d[0], item.y + d[1], cols);
    }
    onLayoutChange(next);
    const moved = next.find((it) => it.i === item.i);
    if (moved) setAnnouncement(describe(moved));
  };

  // ---- render ------------------------------------------------------------------

  const shown = preview ?? layout;
  const ordered = React.useMemo(
    () => [...layout].sort((a, b) => a.y - b.y || a.x - b.x),
    [layout],
  );

  if (stacked) {
    return (
      <div ref={containerRef} className="grid-layout grid-layout_stacked">
        {ordered.map((it) => (
          <div key={it.i} className="grid-item" style={{ height: Math.max(it.h, it.minH ?? 1) * rowHeight + (it.h - 1) * gap }}>
            {renderItem(it, { handleProps: {}, editable: false, active: false })}
          </div>
        ))}
      </div>
    );
  }

  const rows = bottom(shown) + (ghost ? Math.ceil(ghost.rect.height / (rowHeight + gap)) : 0);
  const height = Math.max(0, rows * (rowHeight + gap) - gap);
  const placeholder = ghost && shown.find((it) => it.i === ghost.id);

  return (
    <div ref={containerRef} className="grid-layout" style={{ height }}>
      {width > 0 && placeholder && (
        <div className="grid-placeholder" style={rectStyle(toRect(placeholder))} aria-hidden />
      )}
      {width > 0 &&
        // Render in a stable order so DOM nodes (and chart state) are never re-mounted.
        layout.map((base) => {
          const it = shown.find((s) => s.i === base.i) ?? base;
          const isActive = ghost?.id === it.i;
          const rect = isActive ? ghost.rect : toRect(it);
          return (
            <div
              key={it.i}
              className={`grid-item${isActive ? ` grid-item_active grid-item_${ghost.kind}` : ''}`}
              style={rectStyle(rect)}
            >
              {renderItem(it, {
                editable: true,
                active: isActive,
                handleProps: {
                  onPointerDown: begin('move', it),
                  onKeyDown: onHandleKeyDown(it),
                  'aria-roledescription': 'перетаскиваемый виджет',
                  'aria-description':
                    'Стрелки перемещают виджет по сетке, Shift и стрелки меняют размер. Мышью: тяните за заголовок, размер меняйте за правый нижний угол.',
                } as React.HTMLAttributes<HTMLElement>,
              })}
              <div
                className="grid-resize-handle"
                onPointerDown={begin('resize', it)}
                title="Потяните, чтобы изменить размер"
                aria-hidden
              />
            </div>
          );
        })}
      <div className="grid-sr-only" aria-live="polite">
        {announcement}
      </div>
    </div>
  );
}

function rectStyle(r: Rect): React.CSSProperties {
  return { transform: `translate(${r.left}px, ${r.top}px)`, width: r.width, height: r.height };
}

