import React from 'react';

/** Callback ref + live content-box size (works when the observed node is swapped). */
export function useElementSize<T extends HTMLElement>() {
  const [node, setNode] = React.useState<T | null>(null);
  const [size, setSize] = React.useState({ width: 0, height: 0 });

  React.useLayoutEffect(() => {
    if (!node) return;
    const measure = () => {
      const { width, height } = node.getBoundingClientRect();
      setSize((prev) =>
        Math.abs(prev.width - width) < 0.5 && Math.abs(prev.height - height) < 0.5 ? prev : { width, height },
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(node);
    return () => ro.disconnect();
  }, [node]);

  return [setNode, size] as const;
}
EOF
cat > src/grid/grid.css <<'EOF'
.grid-layout {
  position: relative;
  transition: height 0.2s ease;
}

.grid-layout_stacked {
  display: flex;
  flex-direction: column;
}

.grid-layout:not(.grid-layout_stacked) > .grid-item {
  position: absolute;
  top: 0;
  left: 0;
  transition:
    transform 0.2s ease,
    width 0.2s ease,
    height 0.2s ease;
}

.grid-layout > .grid-item.grid-item_active {
  z-index: 3;
  transition: none;
}

.grid-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  border-radius: 12px;
  background: var(--g-color-base-info-light);
  outline: 2px dashed var(--g-color-line-info);
  outline-offset: -2px;
  transition:
    transform 0.15s ease,
    width 0.15s ease,
    height 0.15s ease;
}

.grid-resize-handle {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 20px;
  height: 20px;
  cursor: nwse-resize;
