}

.grid-item:hover > .grid-resize-handle::after,
.grid-item_resize > .grid-resize-handle::after {
  opacity: 1;
}

body.grid-dragging,
body.grid-dragging * {
  cursor: grabbing !important;
  user-select: none;
}

body.grid-resizing,
body.grid-resizing * {
  cursor: nwse-resize !important;
  user-select: none;
}

