  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .grid-layout,
  .grid-layout > .grid-item,
  .grid-placeholder {
    transition: none;
  }
}
