  --chart-axis: #c3c2b7;
  --chart-muted: #898781;
  --delta-good: #006300;
  --delta-bad: #d03b3b;
  --chart-surface: var(--g-color-base-background);
}

.g-root_theme_dark .dashboard,
.g-root_theme_dark-hc .dashboard {
  --series-1: #3987e5;
  --series-2: #d95926;
  --series-3: #199e70;
  --series-4: #c98500;
  --series-5: #d55181;
  --meter-track: #184f95;
  --chart-grid: #2c2c2a;
  --chart-axis: #383835;
  --delta-good: #0ca30c;
  --delta-bad: #e66767;
