  box-sizing: border-box;
}

.dashboard__header h1 {
  margin: 0;
}

.dashboard__hint {
  margin: 4px 0 0;
}

.dashboard__toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 20px 0 16px;
}

.dashboard__toolbar-spacer {
  flex: 1;
}

.dashboard__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 64px 0;
}

/* ---- widget frame ---------------------------------------------------------- */

.widget {
  position: relative;
