}

.widget__header {
  display: flex;
  flex: none;
  align-items: center;
  gap: 4px;
  min-height: 40px;
  padding: 6px 6px 0 6px;
  touch-action: none;
}

.widget__header_draggable {
  cursor: grab;
}

.widget__title {
  flex: 1;
  min-width: 0;
  margin: 0;
  padding-left: 2px;
}

.widget__actions {
  display: flex;
  flex: none;
